from functools import lru_cache

@lru_cache(maxsize=None)
def fen_repr(n):
    if n == 0:
        return ''
    options = []
    for d in range(1, min(n, 8) + 1):
        options.append(str(d) + fen_repr(n - d))
    options.append('[a-z]' + fen_repr(n - 1))
    return '(' + '|'.join(options) + ')'

for n in range(1, 9):
    print(f"fen_repr({n}) size: {len(fen_repr(n))}")
